lfs_size_t rsize = lfs_min(size, lfs->block_size - off);
lfs_size_t rpos = 0;
while (rpos < size) {
    lfs_size_t read_size = lfs_min(rsize, size - rpos);
    if (lfs_bd_read(lfs, pcache, rcache, hint, block, off + rpos, rcache->buffer, read_size) != 0) {
        return LFS_ERR_CORRUPT;
    }
    int cmp = std::memcmp(buffer + rpos, rcache->buffer, read_size);
    if (cmp != 0) {
        return (cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
    }
    rpos += read_size;
    if (rpos >= lfs->block_size) {
        block++;
        rpos = 0;
        rsize = lfs_min(size - rpos, lfs->block_size);
    }
}
return LFS_CMP_EQ;

